//! Emits the public browser contract; private frontend generation consumes this.
//!
//! `export-web-schema` prints the schema to stdout. `export-web-schema --check` writes nothing:
//! it exits nonzero when the checked-in `schema/web.schema.json` differs from the generated bytes.
use peppy_hosted_api::{
    SessionRenewalResponse, auth_web as auth, billing_web as billing, tester_admin as testers,
    tester_admin_v2 as testers_v2,
};
use std::{path::Path, process::ExitCode};

const CHECKED_IN_SCHEMA: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/schema/web.schema.json");

#[derive(schemars::JsonSchema)]
#[allow(dead_code)]
struct HostedWebContracts {
    capabilities: auth::WebCapabilitiesResponse,
    billing_context: billing::WebBillingContextResponse,
    tester_registry: testers::TesterRegistryResponse,
    tester_initialize: testers::InitializeTestersRequest,
    tester_add: testers::AddTesterRequest,
    tester_remove: testers::RemoveTesterRequest,
    tester_rekey: testers::RekeyTestersRequest,
    tester_reset: testers::ResetTestersRequest,
    tester_mutation: testers::TesterMutationResponse,
    tester_error: testers::TesterErrorResponse,
    tester_registry_v2: testers_v2::TesterRegistryResponseV2,
    tester_unlock_context_v2: testers_v2::TesterUnlockContextResponseV2,
    tester_initialize_v2: testers_v2::InitializeTestersRequestV2,
    tester_add_v2: testers_v2::AddTesterRequestV2,
    tester_remove_v2: testers_v2::RemoveTesterRequestV2,
    tester_rekey_v2: testers_v2::RekeyTestersRequestV2,
    tester_migrate_v2: testers_v2::MigrateTestersRequestV2,
    tester_mutation_v2: testers_v2::TesterMutationResponseV2,
    session: auth::WebSessionResponse,
    session_renewal: SessionRenewalResponse,
    config: auth::WebConfigResponse,
    account: auth::WebAccountResponse,
    billing: billing::BillingSummary,
    plan_catalog: billing::BillingPlans,
    operation: billing::BillingOperationRequest,
    subscribe_request: billing::SubscribeRequest,
    subscribe_response: billing::SubscribeResponse,
    storage_pack_request: billing::StoragePackRequest,
    payment_method_confirm: billing::PaymentMethodConfirmRequest,
    payment_method_setup: billing::PaymentMethodSetupResponse,
}

/// Returns the exact bytes printed by the default mode, including the trailing newline.
fn render() -> String {
    let mut schema = serde_json::to_value(schemars::schema_for!(HostedWebContracts)).unwrap();
    schema["x-peppy-routes"] = serde_json::json!({
        "session": auth::routes::SESSION, "sessionRenew": auth::routes::SESSION_RENEW,
        "appSessionRenew": auth::routes::APP_SESSION_RENEW,
        "authStart": auth::routes::AUTH_START,
        "logout": auth::routes::LOGOUT, "account": auth::routes::ACCOUNT,
        "config": auth::routes::CONFIG, "billing": billing::routes::BILLING,
        "plans": billing::routes::PLANS,
        "subscribe": billing::routes::SUBSCRIBE,
        "paymentAction": billing::routes::PAYMENT_ACTION,
        "reconcile": billing::routes::RECONCILE,
        "paymentMethod": billing::routes::PAYMENT_METHOD,
        "paymentMethodConfirm": billing::routes::PAYMENT_METHOD_CONFIRM,
        "cancel": billing::routes::CANCEL, "resume": billing::routes::RESUME,
        "invoices": billing::routes::INVOICES,
        "storagePack": billing::routes::STORAGE_PACK,
        "testerCapabilities": auth::routes::CAPABILITIES,
        "billingContext": billing::routes::CONTEXT,
        "testerRegistry": testers::routes::REGISTRY,
        "testerInitialize": testers::routes::INITIALIZE,
        "testerEntries": testers::routes::ENTRIES,
        "testerRemove": testers::routes::REMOVE,
        "testerRekey": testers::routes::REKEY,
        "testerReset": testers::routes::RESET,
        "testerRegistryV2": testers_v2::routes::REGISTRY,
        "testerUnlockContextV2": testers_v2::routes::UNLOCK_CONTEXT,
        "testerInitializeV2": testers_v2::routes::INITIALIZE,
        "testerEntriesV2": testers_v2::routes::ENTRIES,
        "testerRemoveV2": testers_v2::routes::REMOVE,
        "testerRekeyV2": testers_v2::routes::REKEY,
        "testerMigrateV2": testers_v2::routes::MIGRATE,
    });
    format!("{}\n", serde_json::to_string_pretty(&schema).unwrap())
}

/// Compares generated bytes with a checked-in file without writing either one.
fn check_contents(checked_in: &Path, generated: &str) -> Result<(), String> {
    let current = std::fs::read_to_string(checked_in)
        .map_err(|error| format!("cannot read {}: {error}", checked_in.display()))?;
    if current == generated {
        Ok(())
    } else {
        Err(format!(
            "{} is out of date; run export-web-schema and update the checked-in file",
            checked_in.display()
        ))
    }
}

fn main() -> ExitCode {
    let arguments = std::env::args().skip(1).collect::<Vec<_>>();
    match arguments
        .iter()
        .map(String::as_str)
        .collect::<Vec<_>>()
        .as_slice()
    {
        [] => {
            print!("{}", render());
            ExitCode::SUCCESS
        }
        ["--check"] => match check_contents(Path::new(CHECKED_IN_SCHEMA), &render()) {
            Ok(()) => ExitCode::SUCCESS,
            Err(message) => {
                eprintln!("{message}");
                ExitCode::FAILURE
            }
        },
        _ => {
            eprintln!("usage: export-web-schema [--check]");
            ExitCode::from(2)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    struct TempFile(std::path::PathBuf);

    impl Drop for TempFile {
        fn drop(&mut self) {
            let _ = std::fs::remove_file(&self.0);
        }
    }

    fn fixture(contents: &str) -> TempFile {
        let path = std::env::temp_dir().join(format!(
            "peppy-web-schema-check-{}.json",
            uuid::Uuid::new_v4()
        ));
        std::fs::write(&path, contents).unwrap();
        TempFile(path)
    }

    #[test]
    fn check_accepts_identical_bytes_and_rejects_drift() {
        let generated = render();
        let matching = fixture(&generated);
        assert_eq!(check_contents(&matching.0, &generated), Ok(()));

        let stale = fixture("{}\n");
        let error = check_contents(&stale.0, &generated).unwrap_err();
        assert!(error.contains("out of date"), "{error}");
    }

    #[test]
    fn check_reports_a_missing_checked_in_file() {
        let missing = std::env::temp_dir().join(format!(
            "peppy-web-schema-missing-{}.json",
            uuid::Uuid::new_v4()
        ));
        let error = check_contents(&missing, &render()).unwrap_err();
        assert!(error.contains("cannot read"), "{error}");
    }

    #[test]
    fn rendered_schema_keeps_the_route_map_and_trailing_newline() {
        let rendered = render();
        assert!(rendered.ends_with("}\n"));
        let value: serde_json::Value = serde_json::from_str(&rendered).unwrap();
        assert_eq!(value["x-peppy-routes"]["session"], auth::routes::SESSION);
    }
}
